toad_implementation.code_blueprint:
canvas {
  size: 800px 1000px;
  fill: #08070A;
  font-family: "Cinzel, serif";
}

>krypta = #08070A;
>stoneGray = #B8A99A;
>sacralLight = #EAE3D2;
>violetDusk = #221B2C;

rect #outerMatte {
  at: center of canvas;
  size: 700px 900px;
  fill: #0C0A0F;
  stroke: >violetDusk;
  stroke-width: 2px;
}

circle #archGlow {
  at: center of #outerMatte offset 0px -120px;
  size: 340px;
  fill: alpha(>sacralLight, 0.26);
}

rect #windowShaft {
  at: center of #outerMatte offset 0px -60px;
  size: 180px 420px;
  fill: >krypta;
  stroke: >stoneGray;
  stroke-width: 3px;
  radius: 90px 90px 0px 0px;
}

circle #roseWindow {
  at: center of #windowShaft offset 0px -110px;
  size: 110px;
  fill: none;
  stroke: >sacralLight;
  stroke-width: 2px;
}

text #seriesTitle {
  at: below #windowShaft offset 80px;
  content: "N O C T U R N E";
  font-size: 26px;
  font-weight: 700;
  color: >sacralLight;
}

text #locationLabel {
  at: below #seriesTitle offset 14px;
  content: "CATHÉDRALE NOTRE-DAME // DE PROFUNDIS";
  font-size: 11px;
  color: >stoneGray;
}
